SELECT b.organization_id AS borg, b.role AS brole, m.name AS mname, m.raw_identifier AS mid, m.country AS mc, count(*) AS n FROM (SELECT DISTINCT p.tender_id AS tid, p.seq AS sq, p.mention_notice_id AS nid FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 1193769 AND p.seq = t.current_seq LIMIT 200) q CROSS JOIN tender_version_parties b ON b.tender_id = q.tid AND b.seq = q.sq AND b.mention_notice_id = q.nid AND b.role IN ('Procedure-Buyer', 'buyer') CROSS JOIN organization_mentions m ON m.notice_id = b.mention_notice_id AND m.section_id = b.mention_section_id GROUP BY b.organization_id, b.role, m.name, m.raw_identifier, m.country ORDER BY n DESC LIMIT 40
